import type { IconRecipe } from "../element";
import { animatePathReveal, clearPathReveal } from "./path-reveal";

export function createSymbolRevealRecipe(firstChild: number, strokes = 1, duration = 0.4): IconRecipe {
  return {
    finish: "hold",
    animate(drawing, returning, track) {
      for (let index = 0; index < strokes; index++) {
        animatePathReveal(drawing.children[firstChild + index] as SVGGeometryElement, returning, track, {
          duration: returning ? 0.3 : duration,
          delay: returning ? 0 : index * 0.2,
          ease: returning ? [0.25, 0.1, 0.35, 1] : "easeInOut",
          opacityDuration: returning ? 0.3 : duration,
        });
      }
    },
    clear(drawing) {
      for (let index = 0; index < strokes; index++) {
        clearPathReveal(drawing.children[firstChild + index] as SVGGeometryElement);
      }
    },
  };
}

import type { IconRecipe } from "../element";
import { animatePathReveal, clearPathReveal } from "./path-reveal";

export function createWindRecipe(delays: number[]): IconRecipe {
  return {
    finish: "restore",
    animate(drawing, returning, track) {
      delays.forEach((delay, index) => animatePathReveal(drawing.children[index] as SVGPathElement, returning, track, {
        duration: returning ? 0.3 : 0.5,
        delay,
        ease: "easeInOut",
        opacityDuration: returning ? 0.3 : 0.5,
        pathOffset: 1,
        preservePose: "until-clear",
      }));
    },
    clear(drawing) {
      delays.forEach((_, index) => clearPathReveal(drawing.children[index] as SVGPathElement));
    },
  };
}
